    ],
  },
  {
    id: 'energy',
    name: 'Energy',
    industries: [
      {
        id: 'integrated',
        name: 'Integrated Oil & Gas',
        stocks: [
          {
            symbol: 'XOM',
            name: 'Exxon Mobil',
            basePrice: 120,
            baseVolume: 15_000_000,
          },
