const EXPERIMENTAL_SECTOR_SPECS = [
  { id: 'consumer', name: 'Consumer Discretionary', code: 'CD' },
  { id: 'staples', name: 'Consumer Staples', code: 'CS' },
  { id: 'industrials', name: 'Industrials', code: 'IN' },
  { id: 'materials', name: 'Materials', code: 'MT' },
